"""Checked against cached official CMO papers; ratings remain in the review ledger."""
import json
from pathlib import Path
P=Path(__file__).parent
rows=[]
def q(y,n,t,s,tags,solution=None):
 rows.append(dict(comp='CMO',y=y,n=n,topic=t,statement=s,tags=tags.split('|'),source=f'https://cms.math.ca/wp-content/uploads/2019/07/exam{y}.pdf',solution=solution))
q(1969,2,'Algebra',r'For $c\ge1$, which is larger: $\sqrt{c+1}-\sqrt c$ or $\sqrt c-\sqrt{c-1}$?','Inequalities|Algebraic identities',r'Rationalization gives reciprocals with denominators $\sqrt{c+1}+\sqrt c$ and $\sqrt c+\sqrt{c-1}$. The first denominator is larger, so the second difference is larger.')
q(1969,3,'Geometry',r'A right triangle has legs $a,b$ and hypotenuse $c$. Prove $a+b\le\sqrt2c$ and determine the equality case.','Geometric inequalities|Triangle geometry',r'From $(a-b)^2\ge0$ we obtain $(a+b)^2\le2(a^2+b^2)=2c^2$. Equality holds exactly when $a=b$.')
q(1969,4,'Geometry',r'An interior point $P$ of an equilateral triangle $ABC$ has perpendicular distances $PD,PE,PF$ to its three sides. Prove $\dfrac{PD+PE+PF}{AB+BC+CA}=\dfrac1{2\sqrt3}$.','Area & dissection|Triangle geometry')
q(1969,5,'Geometry',r'In triangle $ABC$, use the usual side notation $a=BC,b=CA,c=AB$. The internal bisector of $\angle C$ meets $AB$ at $D$. Prove $CD=\dfrac{2ab\cos(C/2)}{a+b}$.','Triangle geometry|Trigonometry|Area & dissection')
q(1969,6,'Algebra',r'Find $1\cdot1!+2\cdot2!+\cdots+n\cdot n!$.','Sums & products|Algebraic identities',r'Since $k\,k!=(k+1)!-k!$, the sum telescopes to $(n+1)!-1$.')
q(1969,7,'Number Theory',r'Prove that no integers $a,b,c$ satisfy $a^2+b^2-8c=6$.','Modular arithmetic|Squares & powers',r'Squares modulo $8$ are $0,1,4$. No sum of two such residues is $6$.')
