q(1970,3,'Combinatorics',r'Each ball in a collection is red or blue and weighs either one or two pounds. Both colours and both weights occur. Prove that two balls differ in both colour and weight.','Extremal arguments|Logic & information')
q(1970,4,'Number Theory',r'(a) Find every positive integer beginning with digit $6$ whose value becomes $1/25$ of the original when that digit is deleted. (b) Prove that deleting the first digit of a positive integer can never leave $1/35$ of its original value.','Digits & bases|Divisibility & GCD')
q(1970,5,'Geometry',r'A quadrilateral has one vertex on each side of a unit square. If its side lengths are $a,b,c,d$, prove $2\le a^2+b^2+c^2+d^2\le4$.','Coordinates & vectors|Geometric inequalities')
