q(1970,9,'Algebra',r'Let $f(n)$ be the sum of the first $n$ terms of $0,1,1,2,2,3,3,\ldots$. Find a formula for $f(n)$ and prove $f(s+t)-f(s-t)=st$ for positive integers $s>t$.','Sequences & recurrences|Sums & products|Parity')
q(1971,1,'Geometry',r'A chord $DB$ contains an interior point $E$ with $DE=3$ and $EB=5$. If the ray from the circle’s centre $O$ through $E$ meets the circle at $C$ with $EC=1$, find the radius.','Power of a point|Circles & tangency')
