q(1973,1,'Algebra',r'(i) Replace $x<1/(4x)$ and $x<0$ by one equivalent inequality. (ii) Find the greatest integer satisfying $4x+13<0$ and $x^2+3x>16$. (iii) Give a rational number between $11/24$ and $6/13$. (iv) Express $100000$ as a product of two integers neither divisible by $10$. (v) Evaluate $1/\log_2 36+1/\log_3 36$ without logarithm tables.','Inequalities|Equations & systems|Algebraic identities')
q(1973,2,'Algebra',r'Solve $|x+3|-|x-1|=x+1$ over the real numbers.','Equations & systems|Functions & graphs')
q(1973,3,'Number Theory',r'If $p$ and $p+2$ are primes greater than $3$, prove $6\mid p+1$.','Primes|Modular arithmetic')
q(1973,4,'Combinatorics',r'A convex nonagon has successive vertices $P_0,\ldots,P_8$ and is triangulated into $P_0P_1P_3$, $P_0P_3P_6$, $P_0P_6P_7$, $P_0P_7P_8$, $P_1P_2P_3$, $P_3P_4P_6$, $P_4P_5P_6$. In how many ways can these seven triangles be assigned distinct labels $\Delta_1,\ldots,\Delta_7$ so that $P_i$ is a vertex of $\Delta_i$ for each $1\le i\le7$?','Counting|Permutations & arrangements')
q(1973,5,'Algebra',r'Put $h(n)=1+1/2+\cdots+1/n$. Prove $n+\sum_{k=1}^{n-1}h(k)=nh(n)$ for every integer $n\ge2$.','Sums & products|Counting')
q(1973,7,'Number Theory',r'The identities $1/1=1/2+1/2$, $1/2=1/3+1/6$, $1/3=1/4+1/12$, $1/4=1/5+1/20$ suggest a general rule. State and prove it. Then prove that for every integer $n>1$ there are positive integers $i\le j$ such that $\dfrac1n=\sum_{k=i}^{j}\dfrac1{k(k+1)}$.','Diophantine equations|Sums & products|Algebraic identities')
q(1974,1,'Algebra',r'(i) For a positive integer $n$, put $x=(1+1/n)^n$ and $y=(1+1/n)^{n+1}$. Prove $y^x=x^y$. (ii) Prove $\sum_{k=1}^{n}(-1)^{k+1}k^2=(-1)^{n+1}\sum_{k=1}^{n}k$ for every positive integer $n$.','Algebraic identities|Sums & products|Induction')
q(1974,2,'Geometry',r'In rectangle $ABCD$, $BC=3AB$. Points $P,Q$ trisect $BC$ in that order from $B$. Prove $\angle DBC+\angle DPC=\angle DQC$.','Trigonometry|Quadrilaterals & polygons')
q(1974,3,'Algebra',r'Let $f(x)=a_0+a_1x+\cdots+a_nx^n$, with $0\le a_i\le a_0$ for $1\le i\le n$. If $b_{n+1}$ is the coefficient of $x^{n+1}$ in $f(x)^2$, prove $b_{n+1}\le\tfrac12f(1)^2$.','Polynomials|Inequalities')
q(1975,1,'Algebra',r'Simplify $\left(\dfrac{1\cdot2\cdot4+2\cdot4\cdot8+\cdots+n\cdot2n\cdot4n}{1\cdot3\cdot9+2\cdot6\cdot18+\cdots+n\cdot3n\cdot9n}\right)^{1/3}$.','Sums & products|Algebraic identities')
q(1975,2,'Algebra',r'A sequence satisfies $a_1=1/2$ and $a_1+\cdots+a_n=n^2a_n$ for every $n\ge1$. Find $a_n$.','Sequences & recurrences|Sums & products')
