old=json.loads((P/'restoration-records.json').read_text()) if (P/'restoration-records.json').exists() else []
keys={(x['comp'],x['y'],x['n']) for x in rows};old=[x for x in old if (x['comp'],x['y'],x['n']) not in keys]
(P/'restoration-records.json').write_text(json.dumps(old+rows,ensure_ascii=False,indent=2)+'\n')
print(len(rows))
